clc; clear; close all;

%Taking the No of Iteration as Input - Iteration/100 = Time of Simulation
N = input("Enter the Number of Iteration: ");
K = input("Enter the Navigation Constant (Generally 3-5): ");

% Initializing the Target Position
rt = NaN(3,N+1);

% Initializing the Missile's Position
rm = NaN(3,N+1);

% Target Trajectory
rt(:,1) = [30000; 20000; 15000];%m --- Initial Position
Vt = [250;-220;223]; 
at = [9; 9; 9];  %m/s^2

%Distance Between the Missile and Target
R = NaN(3,N+1);
Time = NaN(1,N+1);

%%Assuming missile has reached this position and Velocity
r0 = rt(:,1)/vecnorm(rt(:,1));
rm(:,1) = [0;0;0];
Vm = 1200*r0;%m/s - Missile

g = 9.81;%m/s^2
Acc_max = 30*g;%Because we have to take max lateral Acceleration


dt = 0.01;
Time(1) = 0;
fprintf("Initial Distance between the Target and Missile is: %.2f\n",vecnorm(rm(:,1) - rt(:,1))); %[output:415d06f0]


for i = 1:N

    V_rel = Vt - Vm;
    Vm_mag = vecnorm(Vm);
    Vm_hat = Vm/Vm_mag;
    R(:,i) = rt(:,i) - rm(:,i);
    Omega_LOS = cross(R(:,i),V_rel)/norm(R(:,i))^2;
    
    %Latex Command
    Acc_cmd = K*Vm_mag*cross(Omega_LOS,Vm_hat);
    Acc_mag = vecnorm(Acc_cmd);

    if Acc_mag > Acc_max
        Acc_cmd = Acc_cmd * Acc_max/Acc_mag;
    end

    %Updating missile's position
    rm(:,i+1) = rm(:,i) + Vm*dt + Acc_cmd*(dt^2/2);

    %Updating missile velocity
    Vm = Vm + Acc_cmd*dt;
    Vm = 1800 * Vm/norm(Vm);

    %Updating Target position
    rt(:,i+1) = rt(:,i) + Vt*dt + 0.5*at*dt^2;
    
    %Updating Target Velocity
    Vt = Vt + at*dt;

    Time(i+1) = Time(i) + dt;
    R(:,i+1) = rt(:,i+1) - rm(:,i+1);
    
    if (norm(R(:,i+1)) < 20)
        break;
    end

end


if (min(vecnorm(R(:,1:i+1),2,1)) > 20)
    fprintf("The Target accelerated and got out of reach!\n");
end

if (min(vecnorm(R(:,1:i+1),2,1)) <= 20) %[output:group:7aee9781]
    fprintf("Mission Succesfull! Target Eliminated\n"); %[output:507c35ce]

end %[output:group:7aee9781]

%Plotting the Target Trajectory
plot3(rt(1,1:i+1),rt(2,1:i+1),rt(3,1:i+1),marker = "o", Color = "r"); %[output:1735a0a5]
title("Target's Trajectory"); %[output:1735a0a5]
xlabel("X Coordinate"); %[output:1735a0a5]
ylabel("Y Coordinate"); %[output:1735a0a5]
zlabel("Z Coordinate"); %[output:1735a0a5]
hold on; %[output:1735a0a5]
grid on; %[output:1735a0a5]

plot3(rm(1,1:i+1),rm(2,1:i+1),rm(3,1:i+1),marker = "*", Color = "g"); %[output:1735a0a5]
title("Missile's Trajectory"); %[output:1735a0a5]
xlabel("X Coordinate"); %[output:1735a0a5]
ylabel("Y Coordinate"); %[output:1735a0a5]
zlabel("Z Coordinate"); %[output:1735a0a5]

figure; %[output:20c1662d]
plot(Time(1:i+1), vecnorm(R(:,1:i+1),2,1),marker = "+", Color = "b"); %[output:20c1662d]
title("Reletive distance between the Missile and Interceptor!"); %[output:20c1662d]
xlabel("Time in seconds"); %[output:20c1662d]
ylabel("Distance b/w the Target and Missile"); %[output:20c1662d]
grid on; %[output:20c1662d]

Range = vecnorm(R(1,1:i+1),2,1);
[minRange,idx] = min(Range);

fprintf("Time taken to reach closest distance of %.2f m to the Target is: %.2f seconds\n",minRange, Time(idx)); %[output:19fd85b3]


